command:
tmp=$(mktemp -d); export PMW_HOME="$tmp/home" PMW_PROJECT_SLUG=design-completeness-readiness; root="$PMW_HOME/projects/$PMW_PROJECT_SLUG"; mkdir -p "$root/runs" "$root/briefs"; brief="$root/briefs/current.md"; printf '# 产品设计简报：测试
产品简报版本：v2
确认状态：已对齐

## 核心价值判断
- 一句话判断：已确认。
## 数据 / 能力 / 约束与不可虚构项
- 不可虚构项：不得虚构。
' > "$brief"; printf '{"current_run_id":"r1","latest_run_id":"r1","latest_brief":"%s","latest_brief_version":"v2"}
' "$brief" > "$root/project.json"; printf '{"ts":"2099-01-01T00:00:00Z","event":"gate","run_id":"r1","status":"已确认","title":"产品简报确认","summary":"用户确认产品简报"}
{"ts":"2099-01-01T00:00:01Z","event":"gate","run_id":"r1","status":"已确认","title":"线上参考","summary":"新功能，无线上参考，不适用"}
{"ts":"2099-01-01T00:00:02Z","event":"decision","run_id":"r1","status":"已确认","title":"方案方向确认","summary":"默认方向已批准"}
' > "$root/runs/r1.jsonl"; bin/pmw-prototype-board add --scheme 方案A --screen 首页首屏 --brief-path "$brief" --brief-version v2 --goal 提升理解效率 --anti-metric 不制造虚假确定性 --non-fiction 不得虚构真实数据 --canvas-mode standard_first_screen --generation-mode redraw --product-path '先让用户判断是否值得继续' --behavior-assumption '用户愿意先看关键结论再展开细节' --current-loss '当前信息堆叠导致用户无法判断重点' --tradeoff '牺牲完整字段展示，优先保留判断路径' >/dev/null; bin/pmw-dashboard readiness --target prototype --details; rm -rf "$tmp"
